INSERT INTO `agent` VALUES (1,'Astra','控场','加纳','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/ba51d43803082941b0274b66413b0acc972546dd-616x822.png?accountingTag=VAL','加纳特工，掌控宇宙能量，重塑战场空间','引力井：激活星体把敌人拉向中心；新星脉冲：短暂充能后爆炸，震荡范围内敌人；星云：制造球形烟雾遮蔽视野；大招-星界分裂：召唤横贯全图的分裂壁，隔音且挡子弹','https://www.bilibili.com/video/BV1Tf4y147Re/'),(2,'Breach','先锋','瑞典','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/e435c3378b7999a3338b408dbb5da8ba63f91150-616x822.png?accountingTag=VAL','瑞典仿生特工，用动能冲击撕开敌方防线','余震：发射穿墙爆破弹造成范围伤害；闪光点：穿墙闪光致盲敌人；断罪：穿墙冲击波眩晕敌人；大招-轰天震地：全图范围震击，将敌人震飞','https://www.bilibili.com/video/BV1Gg4y167uM/'),(3,'Brimstone','控场','美国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/51e62f3c74356a7501d06feba42ac643133257d7-616x822.png?accountingTag=VAL','来自美国，轨道武器专家，掌控战场全局','激励信号：投掷增益球为队友加速；燃烧弹：发射火焰弹燃烧区域；天空烟幕：在地图任意位置投掷烟幕；大招-轨道打击：呼叫激光轰炸选定区域','https://www.bilibili.com/video/BV1RS421d7uK/'),(4,'Chamber','哨卫','法国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/0f5b668b77499c0051201389d6ac5e7343c9727f-616x822.png?accountingTag=VAL','法国武器设计师，衣冠楚楚、枪械精准','交火点：放置减速陷阱；猎头者：装备精准手枪；传送锚点：放置锚点，范围内瞬间传送；大招-命运降临：装备狙击步枪，击杀后生成减速场','https://www.bilibili.com/video/BV1bK42147S1/'),(5,'Clove','控场','英国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/9f02060077f9d61dbe89555a339e6231006d9b7b-616x822.png?accountingTag=VAL','苏格兰捣蛋鬼，以灵巧身法在敌后制造混乱','捣乱：投掷腐蚀碎片造成伤害；薄暮烟幕：施放烟幕，阵亡后仍可布置；起死回生：击杀或助攻后获得回血；大招-不死之身：阵亡后短暂复活重返战场','https://www.bilibili.com/video/BV1Hj421d7jx/'),(6,'Cypher','哨卫','摩洛哥','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/4a648cdbcbbeef137050deefeaf6a1369c606666-616x822.png?accountingTag=VAL','摩洛哥情报贩子，一人成军的监控大师','绊线：布置绊索陷阱，触发后暴露敌人；网络牢笼：投掷牢笼，触发后限制视野；监控摄像头：放置摄像头发射标记镖；大招-神经窃取：窃取敌人尸体情报，暴露敌方位置','https://www.bilibili.com/video/BV1zv41157V8/'),(7,'Deadlock','哨卫','挪威','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/477284dfe402a85abcf6b07512bcd6f01c8fe60e-616x822.png?accountingTag=VAL','挪威特工，用尖端纳米科技封锁敌人','重力网：布置触发式减速网；声波传感器：侦测声音并眩晕敌人；壁障：放置屏障阻挡敌人移动；大招-毁灭：发射纳米束缠绕并终结敌人','https://www.bilibili.com/video/BV1Vm4y1Y7Jt/'),(8,'Fade','先锋','土耳其','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/e7099cc13a665ed2b556d514e50984393ed49967-616x822.png?accountingTag=VAL','土耳其赏金猎人，以噩梦之力追踪猎物','恶灵：投掷暗影生物追踪敌人；摄魂：暗影球落地后锁定并致盲敌人；幽爪：投掷利爪，标记路径上的敌人；大招-夜幕降临：全图冲击波致聋并标记敌人','https://www.bilibili.com/video/BV1fX4y127vF/'),(9,'Gekko','先锋','美国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/8d88f133f735f6a9077679b1ece754e5624c728e-616x822.png?accountingTag=VAL','洛杉矶小子，带领一帮凶悍可爱的生物伙伴','吞食者：派出莫什爆炸造成范围伤害；闪翼：派出迪兹致盲敌人；震慑波：派出飞翼眩晕敌人；大招-利爪：召唤大鲨猛击，可回收重复使用','https://www.bilibili.com/video/BV16V4y1a7uf/'),(10,'Harbor','控场','印度','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/1246b5c517f6c8fa660e884a7032c1c54994003e-616x822.png?accountingTag=VAL','来自印度海岸，用水墙与波浪主导战场','潮涌：投掷水球阻挡视线；涌泉：施放保护性水墙；潮汐墙：可推动前进的水墙；大招-海啸：召唤全图推进的巨浪','https://www.bilibili.com/video/BV14u411L7i6/'),(11,'Iso','决斗者','中国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/2c35cef9c38283f8478d1e808b1c129f371e50b3-616x822.png?accountingTag=VAL','中国清道夫，进入心流状态单挑制敌','诱饵：投掷诱饵吸引火力；瞄准射击：蓄力直线穿透射击；能量护盾：召唤护盾抵挡子弹；大招-决斗场：展开单挑领域，胜者存活','https://www.bilibili.com/video/BV1t8411r7zL/'),(12,'Jett','决斗者','韩国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/d41286dc9017bf79c0b4d907b7a260c27b0adb69-616x822.png?accountingTag=VAL','韩国疾风少女，敏捷身法无人能及','上升气流：垂直跃起抢占高点；顺风：向移动方向冲刺；凌空：浮空俯瞰战场；大招-剑刃风暴：投掷致命飞刀，击杀后刷新','https://www.bilibili.com/video/BV18s4y1274e/'),(13,'KAY/O','先锋','未知','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/fe52e0efac73ec782b19a54e98a4658b03677407-616x822.png?accountingTag=VAL','为压制超能力者而造的战争机器','压制刃：投掷压制刀沉默敌人；闪光弹：投掷闪光致盲；零时：释放沉默脉冲；大招-湮灭：进入过载状态，压制周围敌人','https://www.bilibili.com/video/BV1Muxtz3Emc/'),(14,'Killjoy','哨卫','德国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/820d36d431fff77b1e1ece39ad6f007746bd31f6-616x822.png?accountingTag=VAL','德国天才发明家，用炮台与机器人防守要地','纳米蜂群：投掷纳米群造成伤害；警报机器人：侦测并减速敌人；炮塔：部署自动炮塔；大招-封锁：大范围封锁并眩晕敌人','https://www.bilibili.com/video/BV1Yw411Q7ox/'),(15,'Miks','控场','克罗地亚','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news_live/39d3f1e45e9a416d6c7bd77cd37accaf16686061-587x900.png?accountingTag=VAL','克罗地亚新星，以声波能量带动全队节奏','M-pulse：投掷声波装置，可切换震荡或治疗模式，脉冲可震荡敌人或持续治疗队友；Harmonize：为指定队友附加攻速与移速增益，击杀可刷新，副开火仅强化自身；Waveform：在地图选定位置生成烟幕（招牌技能）；大招-Bassquake：蓄力释放音波冲击，击退、致聋并减速前方敌人','https://www.youtube.com/watch?v=gictwC-KlTk'),(16,'Neon','决斗者','菲律宾','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/14145d7bf9be17afa80c04ee4fbe200076cc1769-616x822.png?accountingTag=VAL','菲律宾闪电少女，电光火石间撕破防线','震爆弹：弹跳震爆弹眩晕敌人；高速通道：施放两面电子墙；冲刺：高速奔跑并蓄能；大招-超速：进入超速状态，指尖射出闪电','https://www.bilibili.com/video/BV1Wu41127Ec/'),(17,'Omen','控场','未知','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/015a083717e9687de8a741cfceddb836775b5f9f-616x822.png?accountingTag=VAL','记忆中的魅影，在阴影中猎杀敌人','暗影步：短距离瞬移；偏执狂：发射致盲弹；幽蔽烟幕：施放球状烟幕；大招-暗影降临：全图传送突袭','https://www.bilibili.com/video/BV155j2z7Etd/'),(18,'Phoenix','决斗者','英国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/47387e354c34d51b84066bc47af3c5755b92b9c5-616x822.png?accountingTag=VAL','来自英国，火焰之星自带高光','火焰墙：施放火墙阻挡视线；燃烧弹：投掷火焰弹；闪光：弧形闪光致盲；大招-重燃：阵亡后原地复活','https://www.bilibili.com/video/BV1Hh4y1G72A/'),(19,'Raze','决斗者','巴西','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/40b4b242b68afe30d21e7f95bdcacaebca46ea60-616x822.png?accountingTag=VAL','巴西爆炸艺术家，火力与个性同样火爆','炸药包：投掷爆炸物，可当作跳板；爆破机器人：追踪机器人爆炸；彩雷飞溅：投掷分裂榴弹；大招-扫兴至极：发射火箭弹','https://www.bilibili.com/video/BV11o4y1A7fh/'),(20,'Reyna','决斗者','墨西哥','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/7cb513c9b3eae3286449776e85753138436d553c-616x822.png?accountingTag=VAL','墨西哥猎手，单挑之王越战越勇','睥睨：投掷眼球致盲敌人；吞噬：吸取灵魂回复生命；逐散：进入无敌状态；大招-女皇降临：全面强化射速与换弹速度','https://www.bilibili.com/video/BV1dg4y1A7gP/'),(21,'Sage','哨卫','中国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/58a180961a14beb631877921e647c233804853c1-616x822.png?accountingTag=VAL','中国守护者，以一己之力庇护全队','屏障法球：召唤冰墙；减速法球：投掷减速区域；治疗法球：治疗队友；大招-复活：复活阵亡队友','https://www.bilibili.com/video/BV1eV4y1d7dU/'),(22,'Skye','先锋','澳大利亚','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/37ea1466beebb54aad4f16efbad184566cb80368-616x822.png?accountingTag=VAL','来自澳大利亚，与野兽伙伴并肩作战','先驱：引导狼形冲击眩晕敌人；指引之鹰：鹰形闪光致盲；治疗：范围治疗队友；大招-追猎者：派出追猎者追踪敌人','https://www.bilibili.com/video/BV1R5411L758/'),(23,'Sova','先锋','俄罗斯','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/08b3d8822544bd327ebed0768c8b90fcec83d1a5-616x822.png?accountingTag=VAL','来自俄罗斯冻土，猎手之眼无所遁形','猎鹰无人机：侦查并标记敌人；震爆箭：震爆箭震荡敌人；侦察箭：侦察箭扫描区域；大招-猎人之怒：三发穿墙巨箭','https://www.bilibili.com/video/BV1fT411x71c/'),(24,'Tejo','先锋','哥伦比亚','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/3413df9939de606a355c1f88fbfc35f0774c19c9-587x900.jpg?accountingTag=VAL','哥伦比亚情报顾问，弹道打击精准制导','震撼弹：投掷眩晕弹；诱导弹：制导导弹轰炸；侦察仪：扫描区域内的敌人；大招-空袭：呼叫区域轰炸','https://www.bilibili.com/video/BV1ivrjYEEJ6/'),(25,'Veto','哨卫','塞内加尔','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news_live/b89de74fedbb633bdbd7a4423c270957aef18514-587x900.png?accountingTag=VAL','塞内加尔执法者，以基因突变之力无效化敌方能力','Crosscut：放置漩涡装置，范围内可瞬间传送至漩涡位置；Chokehold：投掷变异碎片形成陷阱，束缚敌人并造成致聋与生命衰减；Interceptor：部署拦截器，摧毁一切可被枪火破坏的敌方道具（招牌技能）；大招-Evolution：瞬间完全变异，获得战斗增益与持续回血，并免疫所有减益','https://www.bilibili.com/video/BV1LYB7BMEcL/'),(26,'Viper','控场','美国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/152244f121e61ca32bdd2bea9fc5370e315664fb-616x822.png?accountingTag=VAL','美国化学家，毒雾弥漫的战场掌控者','蛇咬：投掷毒液弹；毒云：施放毒烟；毒墙：施放毒墙；大招-蝰蛇之穴：展开全图毒雾领域','https://www.bilibili.com/video/BV1Ju411j7qx/'),(27,'Vyse','哨卫','韩国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/370e4b820670ef0bac7e685f6e8c5e64d19f1890-587x900.png?accountingTag=VAL','韩国金属大师，液态金属囚禁一切敌人','铁丝网：布置荆棘减速；锐锋：投掷刀刃弹；藤蔓：升起金属墙隔离战场；大招-钢之壁垒：释放致盲冲击','https://www.bilibili.com/video/BV1CPWMe1EnN/'),(28,'Waylay','决斗者','泰国','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/11c2b158d932076d3215749a34b7b4209b48ce44-587x900.png?accountingTag=VAL','泰国棱镜特工，化光而行穿梭战场','光速：向前光速冲刺；棱镜：投掷棱镜闪光；折返：瞬间回溯至标记位置；大招-坍缩：大范围能量坍缩','https://www.bilibili.com/video/BV1GA9hYDEdh/'),(29,'Yoru','决斗者','日本','https://cmsassets.rgpub.io/sanity/images/dsfx7636/news/05e1a996814dd10d7179efee327d29a7be00e912-616x822.png?accountingTag=VAL','日本裂空者，撕裂现实直插敌后','假影步：投掷假身迷惑敌人；闪光：弹跳闪光致盲；传送门：布置传送门穿梭；大招-次元漂移：进入次元隐身移动','https://www.bilibili.com/video/BV1DN41127vh/');
