--
-- Table structure for table `player`
--

DROP TABLE IF EXISTS `player`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `player` (
  `player_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '选手ID',
  `ign` varchar(50) NOT NULL COMMENT '游戏ID',
  `real_name` varchar(50) DEFAULT NULL COMMENT '真实姓名',
  `nationality` varchar(50) DEFAULT NULL COMMENT '国籍',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `player_role` varchar(30) DEFAULT NULL COMMENT '位置',
  `team_id` int(11) DEFAULT NULL COMMENT '所属战队ID',
  `photo_url` varchar(255) DEFAULT NULL COMMENT '选手照片',
  `bio` varchar(255) DEFAULT NULL COMMENT '选手简介',
