INSERT INTO `region` VALUES (1,'中国赛区','CN','VCT 中国赛区','https://static.lolesports.com/leagues/1757677833011_VCT24_CN_Logo_Mark_RGB_Red.png'),(2,'美洲赛区','AMER','VCT 美洲赛区','https://static.lolesports.com/leagues/1757677856494_VCT23_INT_AMERICAS_Logo_MARK_RGB_Orange.png'),(3,'EMEA赛区','EMEA','VCT EMEA赛区','https://static.lolesports.com/leagues/1757677841319_VCT23_INT_EMEA_Logo_MARK_RGB_GREEN.png'),(4,'太平洋赛区','PAC','VCT 太平洋赛区','https://static.lolesports.com/leagues/1757677849568_VCT23_INT_PACIFIC_Logo_MARK_RGB_Blue.png');
/*!40000 ALTER TABLE `region` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `team`
--

DROP TABLE IF EXISTS `team`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `team` (
  `team_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '战队ID',
  `team_name` varchar(100) NOT NULL COMMENT '战队全名',
  `team_tag` varchar(20) NOT NULL COMMENT '战队缩写',
  `region_id` int(11) NOT NULL COMMENT '所属赛区ID',
  `founded_year` year(4) DEFAULT NULL COMMENT '成立年份',
  `logo_url` varchar(255) DEFAULT NULL COMMENT '战队Logo',
  `description` text DEFAULT NULL,
  `honors` text DEFAULT NULL,
  PRIMARY KEY (`team_id`),
  KEY `fk_team_region` (`region_id`),
  CONSTRAINT `fk_team_region` FOREIGN KEY (`region_id`) REFERENCES `region` (`region_id`)
) ENGINE=InnoDB AUTO_INCREMENT=413 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='战队表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `team`
--

LOCK TABLES `team` WRITE;
/*!40000 ALTER TABLE `team` DISABLE KEYS */;
INSERT INTO `team` VALUES (101,'ALL GAMERS','AG',1,1999,'https://static.lolesports.com/teams/1707126806655_AG.png','1999年成立于四川成都，是国内历史最悠久的电竞俱乐部之一，二十余年来在穿越火线、和平精英等项目上斩获众多冠军，是西部电竞的一面旗帜。无畏契约分部组建于2023年，2024年VCT CN联赛元年正式参赛，队中汇聚K1ra、Shr1mp等新生代选手，打法稳健、团队协作出色。','2026 VCT CN启点赛冠军'),(102,'Bilibili Gaming','BLG',1,2017,'https://static.lolesports.com/teams/1707126028220_BLG.png','2017年成立于上海，是哔哩哔哩旗下的电竞俱乐部，英雄联盟分部长期征战LPL，拥有庞大的年轻粉丝群体。无畏契约分部自2023年组建后迅速崛起，以快节奏的进攻风格闻名赛区，核心选手whzy是联赛顶级决斗者，多次在关键局上演个人表演。','2025 VCT CN第一赛段亚军；2025 VCT CN第二赛段冠军（决赛3:1 DRG）'),(103,'DRAGON RANGER GAMING','DRG',1,2016,'https://static.lolesports.com/teams/1707126143797_DRG.png','2016年成立的综合型电竞俱乐部，无畏契约分部是VCT CN联赛的元老队伍之一，自2024年联赛创办起连续参赛、从未缺席。队伍以纪律严明的执行力和扎实的团队配合见长，擅长通过体系化的攻防轮转压制对手。','2025 VCT CN第二赛段亚军'),(104,'EDWARD Gaming','EDG',1,2013,'https://static.lolesports.com/teams/1735920597800_edg1.png','2013年成立于上海，是中国最具影响力的电竞俱乐部之一。无畏契约分部是VCT CN赛区的绝对旗帜，当家明星ZmjjKK（郑永康）与CHICHOO、Smoggy、nobody、S1Mon组成的阵容攻守兼备，代表着中国无畏契约的最高水平。','2024 VALORANT Champions全球冠军赛总冠军（决赛击败Team Heretics，CN赛区首个世界冠军）；2024 VCT CN启点赛、第一赛段、第二赛段冠军（赛季全冠）；2025 VCT CN启点赛冠军；2026 VCT CN第一赛段冠军；联赛共5冠，赛区最成功队伍'),(105,'FunPlus Phoenix','FPX',1,2017,'https://static.lolesports.com/teams/1644542485597_download38.png','2017年成立于上海，旗下英雄联盟分部曾夺得2019年全球总决赛冠军，是国际知名的豪门俱乐部。进入VCT CN联赛时代后，FPX依然是争冠集团常客，以深厚的阵容储备和严谨的战术体系著称。','2022哥本哈根大师赛冠军（决赛3:2 Paper Rex，首支捧起VCT大师赛冠军奖杯的中国战队）；2024 VCT CN启点赛、第一赛段、第二赛段亚军（赛季三亚）'),(106,'JD GAMING','JDG',1,2017,'https://static.lolesports.com/teams/1707126862498_JDG.png','京东集团旗下电竞俱乐部，2017年成立，英雄联盟分部长期位居LPL前列。无畏契约分部自2024年VCT CN联赛元年参赛便展现出强劲竞争力，凭借雄厚的俱乐部资源和科学的训练体系迅速跻身第一集团，队中选手以均衡的个人能力和默契的团队协作著称。','2026 VCT CN第二赛段亚军'),(107,'NOVA ESPORTS','NOVA',1,2016,'https://static.lolesports.com/teams/1741178535000_NOVA.png','香港帝国集团投资的国际电竞品牌，2016年成立，在和平精英等项目上拥有多座冠军奖杯。无畏契约分部是VCT CN联赛常驻队伍，致力于挖掘和培养本土年轻选手，以敢打敢拼的比赛风格著称，多次在联赛中给强队制造麻烦，是赛区青训体系最完善的俱乐部之一。','暂无VCT CN联赛冠军记录'),(108,'TITAN ESPORTS CLUB','TEC',1,2021,'https://static.lolesports.com/teams/1776403053335_TEC.png','体坛传媒集团旗下电竞俱乐部，2021年成立，背靠传统体育媒体资源，在选手包装与运营上独树一帜。无畏契约分部进入VCT CN联赛后一步一个脚印，整体实力逐年提升，凭借扎实的青训体系和团队建设稳步爬升积分榜。','暂无VCT CN联赛冠军记录'),(109,'Trace Esports','TE',1,2023,'https://static.lolesports.com/teams/1736345448590_TE.png','2023年成立于上海的新锐俱乐部，崛起速度堪称赛区奇迹，成为赛区最大黑马。队中heybay、FengF、Biank、LuoK1ng等选手枪法凶悍、进攻节奏极快，极具观赏性的打法为队伍赢得了大批粉丝。年轻的TE仍在成长，目标直指联赛冠军与世界舞台。','2025 VCT CN启点赛亚军；2024晋级VALORANT Champions全球冠军赛'),(110,'TYLOO GAMING','TYL',1,2007,'https://static.lolesports.com/teams/1776403069581_TYLLOGO.png','2007年成立的老牌FPS俱乐部，在CS项目上深耕近二十年，2018年成为首支打进CS:GO Major的中国战队，是中国FPS电竞的一面旗帜。无畏契约分部2024年随VCT CN联赛成立参赛，延续了俱乐部硬朗的枪法传统与冠军血统。','2026 VCT CN第二赛段冠军（决赛3:1 JDG）'),(111,'WOLVES ESPORTS','WOL',1,2024,'https://static.lolesports.com/teams/1707126969882_WOL.png','英超狼队与复星体育共同打造的电竞品牌，2024年成立即进入VCT CN联赛。背靠成熟的职业体育管理体系，俱乐部在选手健康管理、数据分析和科学训练上独树一帜，将英超俱乐部的运营经验带入了无畏契约赛场。','暂无VCT CN联赛冠军记录'),(112,'Xi Lai Gaming','XLG',1,2023,'https://static.lolesports.com/teams/1735920774181_XLGA.PNG','2023年成立的CN赛区新锐战队，2024年跻身VCT CN联赛后迅速刮起青春风暴。这支以激进打法和快速磨合著称的年轻队伍，已经成长为赛区不可忽视的争冠力量。','2025 VCT CN第一赛段冠军（决赛3:1 BLG）；2026 VCT CN启点赛亚军；2026 VCT CN第一赛段亚军（决赛2:3 EDG）'),(201,'100 Thieves','100T',2,2017,'https://static.lolesports.com/teams/1644966311613_100TVAL.png','2017年由前《使命召唤》职业选手Nadeshot创立的电竞品牌，总部位于洛杉矶，以生活方式内容与竞技成绩并重闻名。无畏契约分部进入美洲联赛后迅速崛起，Asuna、Cryocells、Bang等选手组成的阵容进攻犀利，是美洲赛区最具人气与实力的队伍之一。','2024 VCT美洲联赛第一赛段冠军；2026 VCT美洲联赛第二赛段冠军（MVP：Asuna）；2026 VALORANT Champions全球冠军赛季军；2021柏林大师赛四强'),(202,'Cloud9','C9',2,2013,'https://static.lolesports.com/teams/1725635348011_C9-Logo.png','2013年成立的北美老牌电竞豪门，在英雄联盟、CS等项目拥有辉煌历史。无畏契约分部2024年重返VCT美洲联赛，组建以OXY为核心的全新阵容，凭借深厚的俱乐部底蕴迅速站稳脚跟，是美洲赛区不可忽视的传统强队。','暂无VCT美洲联赛冠军记录'),(203,'ENVY','ENVY',2,2007,'https://static.lolesports.com/teams/1764151573361_ENVY_Standard_Light.png','2007年成立的北美老牌俱乐部，在FPS领域积淀深厚。无畏契约分部2025年夺得Ascension Americas冠军，2026赛季正式晋升VCT美洲联赛重返顶级舞台，队中keznit、Demon1等老将压阵，以务实的团队风格立足赛场。','2025 Ascension Americas冠军（2026赛季晋升VCT美洲联赛）；2021柏林大师赛亚军'),(204,'Evil Geniuses','EG',2,1999,'https://static.lolesports.com/teams/1731490673901_VintageEG.png','1999年成立的北美传奇俱乐部，是电竞历史上最悠久的战队之一，横跨多个项目均有冠军入账。无畏契约分部2023年以黑马之姿一路逆袭，在洛杉矶举行的VALORANT Champions全球冠军赛上夺得世界冠军，Demon1、Boostio、Ethan等选手一战成名，谱写俱乐部新的传奇篇章。','2023 VALORANT Champions全球冠军赛总冠军；2023东京大师赛亚军'),(205,'FURIA','FUR',2,2017,'https://static.lolesports.com/teams/1644059765262_FURIA-LOGO.png','2017年成立于巴西的电竞豪门，以激进凶悍的打法风格闻名CS与无畏契约赛场。无畏契约分部2024年进入VCT美洲联赛后迅速成为最具观赏性的队伍之一，深得巴西粉丝热爱，队中alym、artzin等选手敢打敢拼。','2026 VCT美洲联赛启点赛冠军'),(206,'G2 Esports','G2',2,2014,'https://static.lolesports.com/teams/1675329807714_G2-Esports-Logo1.png','2014年成立的国际电竞豪门，总部位于柏林，旗下英雄联盟、CS等分部均处世界顶级水准。无畏契约分部以美洲赛区身份征战VCT美洲联赛，凭借成熟的俱乐部运营和valyn、leaf、trent、BABYBAY、jawgemo等明星选手，长期统治联赛，是近年美洲赛区的绝对霸主。','2025 VCT美洲联赛启点赛、第一赛段、第二赛段三冠王；2026 VCT美洲第一赛段冠军；2024 VCT美洲第一赛段、第二赛段亚军；2025曼谷大师赛亚军；2026 VCT美洲启点赛亚军；2026 VALORANT Champions全球冠军赛四强'),(207,'KRÜ Visa','KRU',2,2020,'https://static.lolesports.com/teams/1630017626481_kru.png','2020年由阿根廷足球传奇阿圭罗创立的电竞俱乐部，是拉美电竞的旗帜。无畏契约分部2021年在全球冠军赛上历史性闯入四强，创造拉美赛区最佳战绩。2026年引入Saadhak、Less等冠军选手重组阵容，凭借超高人气与血性打法成为美洲赛区的票房担当。','2021 VALORANT Champions全球冠军赛四强'),(208,'Leviatán Esports','LEV',2,2020,'https://static.lolesports.com/teams/1644148043034_Leviatncolor.png','2020年成立于智利的电竞俱乐部，是无畏契约美洲赛区的劲旅。2024年迎来队史巅峰，夺得美洲联赛第二赛段冠军并晋级全球冠军赛。队伍以扎实的团队配合和稳健的攻防体系著称，kiNgg、tex等明星选手在南美拥有庞大粉丝基础。','2024 VCT美洲联赛第二赛段冠军；2026伦敦大师赛冠军；2026 VCT美洲联赛第一赛段亚军'),(209,'LOUD','LOUD',2,2019,'https://static.lolesports.com/teams/1644060140569_LOUDGreen.png','2019年成立于巴西的超级俱乐部，以内容运营与竞技成绩双丰收闻名全球。无畏契约分部2022年在伊斯坦布尔举行的VALORANT Champions全球冠军赛决赛中击败OpTic夺得世界冠军，aspas、Less、pANcada、Sacy等选手成为全球明星，是美洲赛区最具影响力的战队之一。','2022、2026 VALORANT Champions全球冠军赛双冠王；2023 VCT美洲联赛冠军；2023 LOCK//IN圣保罗亚军；2024 VCT美洲启点赛亚军；2026 VCT美洲第二赛段亚军'),(210,'MIBR','MIBR',2,2003,'https://static.lolesports.com/teams/1648844013086_mibr_white-logo.png','2003年成立的巴西传奇电竞俱乐部，Made in Brazil之名在CS历史上如雷贯耳，是巴西电竞的一面旗帜。无畏契约分部征战VCT美洲联赛，2026年引进aspas、zekken、Mazino等豪华阵容，延续俱乐部刚猛的枪法传统与冠军底蕴。','暂无VCT美洲联赛冠军记录'),(211,'NRG','NRG',2,2015,'https://static.lolesports.com/teams/1731490666442_NRGWHT.png','2015年成立的北美电竞俱乐部，旗下多个项目均处顶级水平。无畏契约分部2023年组建FNS、s0m、ardiis等明星阵容征战VCT美洲联赛，此后经历多次阵容迭代，如今以Ethan、mada、brawk为核心，是联赛中经验最丰富、底蕴最深厚的队伍之一。','2025 VALORANT Champions全球冠军赛总冠军（决赛击败FNC，队史首个世界冠军）；2025 VCT美洲第二赛段亚军；2023 VCT美洲联赛亚军'),(212,'Sentinels','SEN',2,2016,'https://static.lolesports.com/teams/1739254422982_sent.png','2016年成立的北美人气豪门，拥有全球最大的无畏契约粉丝群体之一。队伍攻守兼备、星光熠熠，TenZ、zekken、Zellsis等明星选手先后效力，是美洲赛区的招牌战队。','2021雷克雅未克大师赛冠军（首届国际大师赛）；2024马德里大师赛冠军；2024 VCT美洲启点赛冠军；2025 VCT美洲启点赛亚军；2025 VCT美洲第一赛段亚军'),(301,'BBL Esports','BBL',3,2020,'https://static.lolesports.com/teams/1674060310685_BBL-GOLD-EMBLEM1.png','2020年成立于土耳其伊斯坦布尔的电竞俱乐部，是土耳其最受欢迎的电竞品牌之一，拥有狂热的主场球迷文化。无畏契约分部自2023年征战VCT EMEA联赛以来稳步成长，2026赛季迎来爆发，以极具侵略性的进攻打法著称，队中选手敢打敢拼，深受土耳其及中东地区粉丝喜爱。','2026 VCT EMEA启点赛冠军'),(302,'Eternal Fire','EF',3,2018,'https://static.lolesports.com/teams/1774348464161_EternalFireLogo.png','2018年成立于土耳其的电竞俱乐部，在CS等项目上拥有辉煌战绩，是土耳其FPS电竞的代表力量。无畏契约分部2025年起征战VCT EMEA联赛，以扎实的枪法和凶悍的对抗风格立足赛区，成长迅速，是联赛中不可小觑的劲旅。','暂无冠军记录（最佳成绩：2026 VCT EMEA第一赛段第四名）'),(303,'FNATIC','FNC',3,2004,'https://static.lolesports.com/teams/1644542427486_download37.png','2004年成立于英国伦敦的传奇电竞俱乐部，是欧洲历史最悠久的电竞组织之一，英雄联盟、CS等多个分部均斩获世界冠军。无畏契约分部是EMEA赛区的旗帜性队伍，以纪律严明的战术执行和体系化的团队配合著称，队长Boaster与Alfajer、Leo、Chronicle等选手长期保持顶级竞争力，几乎每个赛季都处于争冠行列。','2023 LOCK//IN圣保罗冠军；2023东京大师赛冠军；2024 VCT EMEA第一、第二赛段冠军；2025 VCT EMEA第一赛段冠军；2025多伦多大师赛亚军；2025 VALORANT Champions全球冠军赛亚军；2021雷克雅未克大师赛亚军；2023 VCT EMEA亚军'),(304,'FUT Esports','FUT',3,2017,'https://static.lolesports.com/teams/1644342678681_FUT_VRL_DARK.png','2017年成立于土耳其伊斯坦布尔的电竞俱乐部，旗下多个项目均处土耳其顶级水平。无畏契约分部2023年进入VCT EMEA联赛，以硬朗的枪法和顽强的韧性著称，多次打进联赛四强，是土耳其电竞在国际舞台上的重要代表。','暂无冠军记录（多次联赛季军：2023 EMEA季军、2024第一赛段季军、2026第一/第二赛段季军）'),(305,'Gentle Mates','M8',3,2023,'https://static.lolesports.com/teams/1772419824776_M8-Logo.png','2023年成立于法国的电竞俱乐部，由法国顶级主播Gotaga与Squeezie共同创立，背靠庞大的创作者流量迅速成为欧洲人气战队。无畏契约分部2024年进入VCT EMEA联赛，成长速度惊人，年轻阵容冲劲十足。','2026 VCT EMEA启点赛亚军'),(306,'GIANTX','GX',3,2023,'https://static.lolesports.com/teams/1706547566185_GX.png','2023年由英国Excel Esports与西班牙Giants Gaming合并而成的俱乐部，总部位于伦敦与马拉加，是欧洲电竞市场的头部品牌之一。无畏契约分部征战VCT EMEA联赛，凭借成熟的俱乐部运营和多元化阵容持续进步，逐渐跻身赛区前列。','2025 VCT EMEA第二赛段亚军'),(307,'Karmine Corp','KC',3,2020,'https://static.lolesports.com/teams/1651626649157_download1.png','2020年成立于法国的电竞俱乐部，由法国知名主播Kameto创立，拥有欧洲最狂热的粉丝群体之一，主场氛围被誉为电竞界奇观。无畏契约分部2024年进入VCT EMEA联赛便展现出强劲实力，以激情四射的比赛风格和强大的团队凝聚力著称。','2024 VCT EMEA启点赛冠军；2026 VCT EMEA第二赛段冠军'),(308,'NAVI','NAVI',3,2009,'https://static.lolesports.com/teams/1627386036528_Natus_Vincere_2021_lightmode.png','2009年成立于乌克兰的传奇电竞俱乐部，在CS项目上拥有多座世界冠军奖杯，是FPS电竞历史上最伟大的战队之一。无畏契约分部自2023年征战VCT EMEA联赛，延续俱乐部深厚的FPS底蕴，以稳健的战术体系和出色的个人能力立足赛区。','暂无冠军记录（2023 LOCK//IN圣保罗四强）'),(309,'PCIFIC Esports','PCF',3,2022,'https://static.lolesports.com/teams/1766141618825_PCIFIC_Esports_allmode.png','2022年成立的电竞俱乐部，无畏契约分部是VCT EMEA联赛的一员，队伍以务实的团队风格和快速的新人培养能力著称，近年来排名稳步提升，正在向赛区第一集团迈进。','暂无冠军记录（最佳成绩：2025 VCT EMEA第二赛段季军）'),(310,'Team Heretics','TH',3,2016,'https://static.lolesports.com/teams/1674060672534_600px-Team_Heretics_2022_allmode1.png','2016年成立于西班牙马德里的电竞俱乐部，是无畏契约EMEA赛区的劲旅。队伍以极具创意的战术和大胆的临场发挥著称，Boo、benjyfishy、MiniBoo、Wo0t等年轻选手组成的阵容活力十足，2024年曾一路杀入世界冠军赛决赛，是欧洲无畏契约的人气担当。','2024 VALORANT Champions全球冠军赛亚军；2024上海大师赛亚军；2024 VCT EMEA启点赛、第一赛段亚军；2025 VCT EMEA第一赛段亚军；2026 VCT EMEA第一赛段冠军'),(311,'Team Liquid','TL',3,2000,'https://static.lolesports.com/teams/1637252586938_teamliquid.png','2000年成立于荷兰的传奇电竞俱乐部，是世界上历史最悠久的电竞组织之一，横跨二十多个项目。无畏契约分部是VCT EMEA联赛的元老强队，以严谨的战术体系和深厚的人才储备著称，长期稳居赛区争冠行列。','2023 VCT EMEA联赛冠军；2025 VCT EMEA第二赛段冠军；2025 VCT EMEA启点赛亚军；2026 VCT EMEA第二赛段亚军；2021全球冠军赛四强'),(312,'Team Vitality','VIT',3,2013,'https://static.lolesports.com/teams/1722030793680_VITALITY_YELLOW.png','2013年成立于法国的电竞豪门，英雄联盟、CS等分部均为世界顶级水准。无畏契约分部2025年重组阵容后重返巅峰，队中汇聚多位国际明星选手，以全面均衡的战术体系著称，是EMEA赛区最具竞争力的队伍之一。','2025 VCT EMEA启点赛冠军；2024 VCT EMEA第二赛段亚军；2026 VCT EMEA第一赛段亚军；2026 VALORANT Champions全球冠军赛亚军'),(401,'DetonatioN FocusMe','DFM',4,2013,'https://static.lolesports.com/teams/1675669923678_190px-DetonatioN_FocusMe_2022_darkmode1.png','2013年成立的日本电竞俱乐部，隶属DetonatioN Gaming，是日本历史最悠久、成绩最辉煌的电竞组织之一，英雄联盟分部长期统治LJL赛区。无畏契约分部代表日本征战VCT太平洋联赛，以细腻的战术素养和顽强的比赛作风著称，是日本电竞在国际舞台上的重要代表。','暂无冠军记录'),(402,'FULL SENSE','FS',4,2020,'https://static.lolesports.com/teams/1705915075330_FULLSENSE.png','2020年成立于泰国的电竞俱乐部，是泰国无畏契约的代表战队，深受东南亚粉丝喜爱。无畏契约分部2023年起征战VCT太平洋联赛，以凶悍的枪法和快速的进攻节奏著称，2026赛季闯入联赛决赛，实现了队史突破。','2026 VCT太平洋第一赛段亚军'),(403,'Gen.G','GEN',4,2017,'https://static.lolesports.com/teams/1775114509356_GENGLOGO_GOLD.png','2017年成立于韩国首尔的国际电竞俱乐部，英雄联盟分部是LCK的顶级强队。无畏契约分部2024年迎来巅峰赛季，以Meteor、t3xture、Karon等选手组成的阵容横扫赛区，攻防体系极为成熟，是太平洋赛区的豪门代表。','2024 VCT太平洋启点赛、第二赛段冠军；2024上海大师赛冠军；2024马德里大师赛亚军；2024 VCT太平洋第一赛段亚军；2025 VCT太平洋第一赛段亚军'),(404,'GLOBAL ESPORTS','GE',4,2017,'https://static.lolesports.com/teams/1677137854820_GERedandBlue-WhiteBG.png','2017年成立的印度电竞俱乐部，是印度电竞的先驱与旗帜，在多个项目上拥有国际影响力。无畏契约分部征战VCT太平洋联赛，2026赛季迎来队史巅峰，凭借出色的整体配合和大赛表现力迅速跻身赛区强队行列。','2026 VCT太平洋第二赛段冠军；2026 VCT太平洋第一赛段季军'),(405,'Kiwoom DRX','KRX',4,2012,'https://static.lolesports.com/teams/1774420104898_.png','2012年成立的韩国电竞豪门（Kiwoom证券冠名），英雄联盟分部曾夺得2022年全球总决赛冠军。无畏契约分部是VCT太平洋联赛的元老强队，以BuZz、stax等明星选手和严谨的战术纪律著称，长期处于争冠行列。','2025 VCT太平洋启点赛冠军；2023 VCT太平洋联赛亚军；2024 VCT太平洋第二赛段亚军；2023 LOCK//IN四强；2022全球冠军赛四强；2025全球冠军赛季军'),(406,'NONGSHIM REDFORCE','NS',4,2018,'https://static.lolesports.com/teams/1674219422693_NS_.png','2018年成立的韩国电竞俱乐部，隶属于知名食品集团农心，是韩国电竞的新锐力量。无畏契约分部2026赛季强势爆发，在太平洋联赛和国际赛场双线告捷，以均衡的阵容实力和稳健的团队执行惊艳了整个赛区。','2026圣地亚哥大师赛冠军；2026 VCT太平洋启点赛冠军；2026 VCT太平洋第二赛段亚军'),(407,'Paper Rex','PRX',4,2020,'https://static.lolesports.com/teams/1630018120582_paper-rex-2021.png','2020年成立于新加坡的无畏契约俱乐部，是太平洋赛区最具标志性的战队。队伍以独创的激进攻防风格闻名全球，f0rsakeN、d4v41、Jinggg、mindfreak等选手个性鲜明，几乎每个赛季都是冠军的有力争夺者，深受全球粉丝喜爱。','2025多伦多大师赛冠军；2023 VCT太平洋联赛冠军；2024 VCT太平洋第一赛段冠军；2025 VCT太平洋第二赛段冠军；2026 VCT太平洋第一赛段冠军；2023全球冠军赛亚军；2022哥本哈根大师赛亚军；2026圣地亚哥大师赛亚军；2026伦敦大师赛亚军'),(408,'Rex Regum Qeon','RRQ',4,2013,'https://static.lolesports.com/teams/1707306458590_LOGO_RRQ_orange.png','2013年成立于印度尼西亚的电竞俱乐部，是东南亚历史最悠久、影响力最大的电竞组织之一。无畏契约分部征战VCT太平洋联赛，2025赛季迎来队史高光，以顽强的团队作风和出色的新人培养能力立足赛区。','2025 VCT太平洋第一赛段冠军；2025 VCT太平洋第二赛段亚军'),(409,'T1','T1',4,2004,'https://static.lolesports.com/teams/1677137430839_T1_infoboximage1.png','2004年成立的韩国传奇电竞俱乐部，英雄联盟分部五夺全球总决赛冠军，旗下拥有Faker等世界级明星，是全球最具影响力的电竞品牌之一。无畏契约分部2025年组建豪华阵容征战VCT太平洋联赛，迅速跻身顶级强队行列。','2025曼谷大师赛冠军；2025 VCT太平洋启点赛亚军；2026 VCT太平洋启点赛亚军'),(410,'Team Secret','TS',4,2014,'https://static.lolesports.com/teams/1636575342048_team-secret-on-dark.png','2014年成立的国际电竞俱乐部，DOTA2分部曾多次斩获国际大赛冠军，在东南亚拥有庞大粉丝基础。无畏契约太平洋分部延续俱乐部的冠军基因，以灵活的战术风格征战VCT太平洋联赛。','暂无冠军记录'),(411,'VARREL','VL',4,2015,'https://static.lolesports.com/teams/1706170514062_VARREL_darkmode.png','2015年成立的日本电竞俱乐部，在日本国内赛事中拥有出色战绩。无畏契约分部征战VCT太平洋联赛，以务实的团队风格和坚韧的比赛态度著称，是日本无畏契约的重要代表。','暂无冠军记录（最佳成绩：2026 VCT太平洋第二赛段第四名）'),(412,'ZETA DIVISION','ZETA',4,2018,'https://static.lolesports.com/teams/1630017899610_zeta.png','2018年成立的日本电竞俱乐部，是日本无畏契约最具代表性的战队。2022年在雷克雅未克大师赛上历史性闯入四强，创造了日本战队在国际大赛的最佳战绩，点燃了日本无畏契约的热情。','2022雷克雅未克大师赛四强（日本战队国际大赛最佳战绩）');
