/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `team_tournament` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `team_id` int(11) NOT NULL COMMENT '战队ID',
  `tournament_id` int(11) NOT NULL COMMENT '赛事ID',
  `placement` varchar(50) DEFAULT NULL COMMENT '名次',
  `wins` int(11) DEFAULT 0 COMMENT '胜场',
  `losses` int(11) DEFAULT 0 COMMENT '负场',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_team_tournament` (`team_id`,`tournament_id`),
  KEY `fk_tt_tournament` (`tournament_id`),
  CONSTRAINT `fk_tt_team` FOREIGN KEY (`team_id`) REFERENCES `team` (`team_id`),
  CONSTRAINT `fk_tt_tournament` FOREIGN KEY (`tournament_id`) REFERENCES `tournament` (`tournament_id`)
) ENGINE=InnoDB AUTO_INCREMENT=638 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='战队赛事表';
/*!40101 SET character_set_client = @saved_cs_client */;

